package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.world.phys.Vec3;
/** Production controller and policy, synthetic readers and prescribed trajectory at an arbitrary synthetic origin. No live physics claim. */
public final class StepDownEngineChecks {
 static int checks;static final JsonArray cases=new JsonArray();
 static void check(boolean c,String why){checks++;if(!c)throw new AssertionError(why);}
 static void reject(Runnable r){checks++;try{r.run();}catch(ClientActionRequest.Rejected|IllegalArgumentException expected){return;}throw new AssertionError("Expected refusal");}
 static JsonObject point(double x,double y,double z){JsonObject j=new JsonObject();j.addProperty("x",x);j.addProperty("y",y);j.addProperty("z",z);return j;}
 static ClientActionRequest request(){JsonObject j=new JsonObject();j.addProperty("action_id","synthetic-descent");j.addProperty("action","follow_path");j.addProperty("timeout_ms",8000);j.addProperty("capability_route",true);j.addProperty("min_health",12);j.add("expected_origin",point(.5,1,.5));JsonArray a=new JsonArray();a.add(point(1.5,0,.5));j.add("waypoints",a);return new ClientActionRequest("synthetic-descent","follow_path",8000,List.of(new ClientActionRequest.Point(1.5,0,.5,false)),null,null,null,-1,false,false,-1,-1,0,null,j);}
 record F(Minecraft mc,ScopedStepDownMovement m,ActionRegistry.Entry entry,long admitted){}
 static F start(){Hooks.reset();ClientActions.reset();MovementBudget.active=false;WorldGeneration.value="world";IntegratedServerIdentity.value="server";NavigationPositionGuard.value=0;BridgeServer.held=false;Minecraft mc=new Minecraft();var r=request();var m=new ScopedStepDownMovement(mc,r,System.nanoTime(),mc.level.time);var e=ClientActions.install(r,m);m.activate(e);return new F(mc,m,e,System.nanoTime());}
 static void step(F f,int tick,double x,double y,boolean ground,double vy,float fall){f.entry.ticks=tick;f.mc.player.x=x;f.mc.player.y=y;f.mc.player.ground=ground;f.mc.player.velocity=new Vec3(0,vy,0);f.mc.player.fallDistance=fall;f.m.beforeEffect(f.mc);}
 static F trajectory(){F f=start();step(f,0,.8,1,true,-.0784,0);step(f,1,1.1,1,true,-.0784,0);step(f,2,1.31,1,false,-.0784,0);
  double drag=(double).98F,y=1,v=-.08*drag;int tick=3;
  while(y+v>0){y+=v;v=(v-.08)*drag;step(f,tick++,1.5,y,false,v,(float)(1-y));}
  step(f,tick++,1.5,0,true,-.0784,0);step(f,tick,1.5,0,true,-.0784,0);check(f.m.settled(),"exact settled landing");return f;}
 static void scenario(String n,Runnable r){r.run();cases.add(n);System.out.println("PASS "+n);}
 static Object field(Object o,String name){try{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new AssertionError(e);}}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);
  scenario("one-step-four-directions-and-pedestal",()->{for(int[]d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){var b=ScopedStepDownPolicy.route(.5,1,.5,List.of(new ScopedStepDownPolicy.Point(.5+d[0],0,.5+d[1])));check(b.prism().cells()==180,"180 cells");check(b.solid(0,0,0)&&b.solid(1,-1,0)&&!b.solid(1,0,0),"exact supports");}for(double dy:new double[]{0,1,-2})reject(()->ScopedStepDownPolicy.route(.5,1,.5,List.of(new ScopedStepDownPolicy.Point(1.5,1+dy,.5))));reject(()->ScopedStepDownPolicy.route(.5,1,.5,List.of(new ScopedStepDownPolicy.Point(1.5,0,1.5))));});
  scenario("synthetic-standard-gravity-trajectory",()->trajectory());
  scenario("offledge-sameY-same-tick-no-age-increment",()->{var f=start();step(f,0,.8,1,true,-.0784,0);step(f,1,1.1,1,true,-.0784,0);step(f,2,1.31,1,false,-.0784,0);for(int i=0;i<3;i++)f.m.beforeEffect(f.mc);check((Integer)field(f.m,"airborneSince")==2 && (Integer)field(f.m,"sampleActionTick")==2,"same tick stable");});
  scenario("airborne-at-admission-refused",()->{var f=start();ClientActions.end(true);f.mc.player.ground=false;reject(()->new ScopedStepDownMovement(f.mc,request(),System.nanoTime(),f.mc.level.time));});
  scenario("wrong-vertical-upward-below-floor-skipped-descent",()->{for(int n=0;n<5;n++){var f=start();int k=n;reject(()->{switch(k){case 0->step(f,1,.6,1.01,false,.1f,0);case 1->step(f,1,.6,-.1,false,-.2f,1.1f);case 2->step(f,1,.6,0,true,-.0784,0);case 3->step(f,1,.6,.5,true,-.0784,0);case 4->step(f,1,.6,1,false,-.51f,0);}});}});
  scenario("same-tick-and-single-tick-drop-limit",()->{var f=start();step(f,0,.8,1,true,-.0784,0);step(f,1,1.1,1,true,-.0784,0);step(f,2,1.31,1,false,-.0784,0);step(f,2,1.31,.7,false,-.2f,.3f);reject(()->step(f,2,1.31,.4,false,-.3f,.6f));var g=start();step(g,0,.8,1,true,-.0784,0);step(g,1,1.1,1,true,-.0784,0);step(g,2,1.31,1,false,-.0784,0);reject(()->step(g,3,1.31,.4,false,-.3f,.6f));});
  scenario("second-departure-and-unsettled-landing",()->{var f=trajectory();f.mc.player.velocity=new Vec3(.02,-.0784,0);check(!f.m.settled(),".03 legacy speed insufficient");check(f.m.terminal(true).get("landed").getAsBoolean(),"landed phase differs from stopped");f.mc.player.ground=false;reject(()->f.m.beforeEffect(f.mc));});
  scenario("budget-gravity-autojump-food-hazard-refusals",()->{for(int i=0;i<10;i++){var f=start();switch(i){case 0->MovementBudget.active=true;case 1->f.mc.player.noGravity=true;case 2->f.mc.player.gravity=.04;case 3->f.mc.player.autoJump=true;case 4->f.mc.player.autoJumpTime=1;case 5->f.mc.options.autoJump=true;case 6->f.mc.player.food.level=19;case 7->f.mc.player.horizontalCollision=true;case 8->f.mc.player.climbing=true;case 9->f.mc.player.fallDistance=Float.NaN;}reject(()->f.m.beforeEffect(f.mc));}var f=start();ClientActions.end(true);MovementBudget.active=true;reject(()->new ScopedStepDownMovement(f.mc,request(),System.nanoTime(),f.mc.level.time));});
  scenario("terrain-floor-headroom-fluid-unknown",()->{for(int i=0;i<5;i++){var f=start();switch(i){case 0->f.mc.level.loaded=false;case 1->f.mc.level.fluid=true;case 2->f.mc.level.floorId="minecraft:ice";case 3->f.mc.level.air=false;case 4->f.mc.level.solid=false;}reject(()->f.m.beforeEffect(f.mc));}});
  scenario("owner-counter-pose-mutation-after-hooks",()->{for(int i=0;i<5;i++){var f=start();int k=i;Hooks.once("friction",0,()->{switch(k){case 0->ClientActions.active=null;case 1->ClientActions.ownershipRevision++;case 2->f.entry.ticks++;case 3->MovementBudget.active=true;case 4->f.mc.player.y-=.1;}});reject(()->f.m.beforeEffect(f.mc));check((Integer)field(f.m,"checks")==0,"failed check does not append successful evidence");}});
  scenario("airborne-action-tick-budget",()->{var f=start();step(f,1,.8,1,false,-.0784,0);for(int t=2;t<=21;t++)step(f,t,.8,1,false,-.0784,0);reject(()->step(f,22,.8,1,false,-.0784,0));});
  scenario("airborne-cancel-neutral-not-stopped",()->{var f=start();step(f,1,.8,1,false,-.0784,0);for(boolean neutral:new boolean[]{true,false}){var t=f.m.terminal(neutral);check(t.get("input_neutral").getAsBoolean()==neutral && !t.get("velocity_stopped_proven").getAsBoolean() && !t.get("landed").getAsBoolean(),"no false landing after cancel");}ClientActions.end(true);check(f.entry.result.get("input_release_confirmed").getAsBoolean(),"registry release proof");});
  scenario("strict-intent-and-negative-world-geometry",()->{for(String key:List.of("min_health","waypoints")){var j=request().original().deepCopy();j.remove(key);reject(()->ScopedStepDownMovement.validateIntent(j));}var extra=request().original().deepCopy();extra.addProperty("pickup_target",true);reject(()->ScopedStepDownMovement.validateIntent(extra));var b=ScopedStepDownPolicy.route(-.5,1,-.5,List.of(new ScopedStepDownPolicy.Point(.5,0,-.5)));check(b.startX()==-1&&b.startZ()==-1,"negative floor coordinates");check(!b.contains(-.3,.9,-.5),"pedestal side body collision");reject(()->ScopedStepDownPolicy.route(.5,-63,.5,List.of(new ScopedStepDownPolicy.Point(1.5,-64,.5))));});
  scenario("post-hook-attribute-and-original-deadline",()->{for(int i=0;i<3;i++){var f=start();int k=i;Hooks.once("friction",0,()->{switch(k){case 0->f.mc.player.gravity=.04;case 1->f.mc.player.ga=new net.minecraft.world.entity.ai.attributes.AttributeInstance(()->.08);case 2->f.mc.player.attrs=new net.minecraft.world.entity.ai.attributes.AttributeMap();}});reject(()->f.m.beforeEffect(f.mc));}var f=start();ClientActions.end(true);reject(()->new ScopedStepDownMovement(f.mc,request(),System.nanoTime()-8_000_000_001L,f.mc.level.time));});
  scenario("action-ticks-159-160-regression-gap",()->{var f=start();for(int i=0;i<160;i++){f.entry.ticks=i;f.m.beforeEffect(f.mc);}f.entry.ticks=160;reject(()->f.m.beforeEffect(f.mc));var g=start();g.entry.ticks=2;reject(()->g.m.beforeEffect(g.mc));});
  var f=trajectory();JsonObject meta=new JsonObject();meta.addProperty("source_tick",f.m.sourceTick);meta.addProperty("source_nano",Long.toString(f.m.sourceNano));meta.addProperty("admitted_nano",Long.toString(f.admitted));meta.addProperty("action_session",f.m.session);meta.addProperty("player_uuid",f.m.playerUuid);meta.addProperty("world_generation",f.m.worldGeneration);meta.addProperty("integrated_server_instance",f.m.serverIdentity);meta.addProperty("last_world_tick",f.mc.level.time);
  Files.writeString(out.resolve("actual-footprint.json"),new GsonBuilder().serializeNulls().create().toJson(f.m.facts()),StandardOpenOption.CREATE_NEW);Files.writeString(out.resolve("actual-terminal.json"),BridgeJson.toJson(f.m.terminal(true)),StandardOpenOption.CREATE_NEW);Files.writeString(out.resolve("actual-metadata.json"),meta.toString(),StandardOpenOption.CREATE_NEW);
  JsonObject report=new JsonObject();report.addProperty("assertions",checks);report.add("cases",cases);report.addProperty("scope","Fresh production descent controller/policy with synthetic engine readers; prescribed source-faithful vanilla-gravity recurrence, not real physics execution");Files.writeString(out.resolve("engine-result.json"),report.toString(),StandardOpenOption.CREATE_NEW);System.out.println("PASS checks="+checks);
 }
}
